        heading: '2. 日本の気候区分',
        body: `日本は南北に約3,000km伸びる列島で、亜熱帯から亜寒帯まで多様な気候があります。入試では6つの気候区を覚え、「雨温図」から地域を特定する問題が頻出です。

■ 6つの気候区

①太平洋側気候（東京・高知・静岡など）
・夏：南東の季節風が多雨をもたらす → 高温多雨
・冬：乾燥した晴れが多い（空っ風）
・例）東京の年降水量：約1,500mm

②日本海側気候（新潟・金沢・秋田など）
・冬：北西の季節風が日本海の水分を吸収 → 豪雪
・夏：フェーン現象で高温・乾燥
・例）新潟市の年降水量：約1,800mm（冬の降水量が多い）

③中央高地気候（長野・松本・甲府など）
・夏涼しく冬厳しい内陸性気候
・年較差（夏と冬の気温差）が大きい
・降水量は少なめ（山に囲まれているため）

④瀬戸内気候（岡山・広島・高松など）
・中国山地と四国山地の両方に守られ、年間を通じて晴れが多く温暖・少雨
・例）高松市の年降水量：約1,100mm（日本で最も少ない都市圏の一つ）

⑤南西諸島気候（沖縄・奄美）
・亜熱帯性気候。年平均気温20℃以上
・台風の影響を受けやすい
・さんごしょうやマングローブが見られる

⑥北海道気候（札幌・帯広・旭川）
・冷帯（亜寒帯）。梅雨がない
・冬の積雪量が多く、年較差が大きい
・例）旭川市では-40℃以下を記録したことがある

■ 雨温図の読み方
・横軸：月（1〜12月）、左縦軸：気温（折れ線グラフ）、右縦軸：降水量（棒グラフ）
・降水量の多い月が「夏」かどうか → 太平洋側はYes、日本海側はNoに近い
・気温が全体的に高い → 南の地域（那覇など）

■ 季節風とフェーン現象
・北西の季節風（冬）が日本海側に雪をもたらし、山を越えると乾いた暖かい風になる（フェーン現象）
・例）富山や新潟では、冬でも突然気温が10℃以上上がることがある

■ 台風のルート
・フィリピン東海上で発生 → 北上 → 九州・四国・紀伊半島などに上陸 → 太平洋側を北東に抜ける
・上陸直前の「右側半円」が風雨最強（危険半円）

★ ポイント：雨温図で最も出やすいのは「那覇（南西諸島）」「札幌（北海道）」「新潟（日本海側）」「高松（瀬戸内）」の4都市。それぞれの特徴をグラフのパターンで覚えよう。

⚠ 注意：「フェーン現象」は「山を越えた後の乾燥した風が気温上昇をもたらす」現象。日本海側が豪雪になる理由と表裏一体です。混同しないよう注意。`,
