板垣退助らが1874年に「民撰議院設立建白書」を政府に提出し、国民が選ぶ議会の設立を求めた運動。全国に政治結社（立志社・愛国社）が広まり、国会開設要求が高まった。政府は1881年に「国会開設の詔」を発し、10年後の国会開設を約束した。

