        heading: '1. 地球環境問題の現状',
        body: `■ 地球温暖化
大気中の温室効果ガス（CO₂・メタン・亜酸化窒素・フロン類など）が増加し、地球の平均気温が上昇する現象。主な原因は化石燃料（石油・石炭・天然ガス）の燃焼・森林破壊・畜産業のメタン排出など。IPCC（気候変動に関する政府間パネル）が科学的評価報告書を定期発行。主な影響：海面上昇（太平洋の島国・バングラデシュへの影響）、異常気象（洪水・干ばつ・台風の激甚化）、生態系の破壊・珊瑚礁の白化。

■ 酸性雨
工場・自動車から排出される二酸化硫黄（SO₂）・窒素酸化物（NOx）が大気中の水分と反応してpH5.6以下の酸性雨になる。欧州では湖沼の魚類絶滅・森林枯死・石造建築（パルテノン神殿など）の腐食が問題に。越境汚染のため国際的な取り組みが必要。日本では瀬戸内海・東北地方でも観測されている。

■ オゾン層破壊
フロン類（冷蔵庫・エアコンの冷媒・スプレー噴射剤）が成層圏に達しオゾン（O₃）を分解。オゾン層は太陽からの有害な紫外線（UV-B）を吸収するが、破壊されると紫外線が増加→皮膚がん・白内障・免疫機能低下のリスクが高まる。南極上空に「オゾンホール」が発見（1980年代）→1987年のモントリオール議定書でフロン類の生産・消費を段階的に禁止。現在はオゾン層の回復が確認されつつある。

■ 砂漠化
年降水量250mm以下の乾燥・半乾燥地域で、過耕作・過放牧・乱伐・気候変動により土地の生産力が失われる現象。サヘル地帯（アフリカのサハラ砂漠南縁）・中国内陸部（黄土高原・内モンゴル）が深刻。中国の「緑の長城」（防砂林の造成）・国連砂漠化対処条約（UNCCD・1994年）が対策として機能している。

⚠ 注意：地球温暖化・オゾン層破壊・酸性雨はそれぞれ原因物質が異なる。混同しやすいので整理すること（CO₂→温暖化、フロン→オゾン層破壊、SO₂/NOx→酸性雨）。

★ ポイント：環境問題は「越境汚染」の性格を持つため、一国だけの解決が不可能。国際条約・国際協力の必要性と、その実現の難しさ（先進国vs途上国の対立）がポイント。`,
