        heading: '2. 環境条約と国際的取り組み',
        body: `■ ストックホルム会議（1972年）
スウェーデンのストックホルムで開催された国連人間環境会議。「かけがえのない地球」をスローガンに「人間環境宣言」を採択。環境問題を国際的に議論した最初の大規模な会議で、国連環境計画（UNEP）の設立につながった。

■ リオサミット（1992年）
ブラジル・リオデジャネイロで開かれた地球サミット（国連環境開発会議）。「持続可能な開発」の原則を確認し、気候変動枠組条約・生物多様性条約・アジェンダ21を採択。環境問題が経済発展とセットで論じられるようになった転換点。

■ 京都議定書（1997年）
COP3（気候変動枠組条約第3回締約国会議）で採択。先進国のみに温室効果ガスの数値目標削減義務を課した（日本：2008〜12年に1990年比6%削減）。最大排出国のアメリカが離脱（2001年）、中国・インドなど途上国は削減義務なしという不均衡が問題となり実効性が限られた。

■ パリ協定（2015年）
COP21で採択。196か国・地域すべてが参加する初の普遍的な気候変動枠組み。目標：産業革命前比の気温上昇を2℃未満（努力目標：1.5℃）に抑制。各国が自主的に国別削減目標（NDC）を設定し5年ごとに更新する仕組み（ラチェット機構）。先進国は途上国への資金支援（年間1000億ドル）を約束。トランプ政権下でのアメリカ離脱→バイデン政権で復帰という経緯もある。

■ COPの意味と各国の目標
COP（Conference of the Parties）は条約の「締約国会議」の略称。気候変動枠組条約のCOPは毎年開催。日本は2030年までに2013年比46%削減・2050年カーボンニュートラルを目標に掲げる。

⚠ 注意：京都議定書（先進国のみ義務）とパリ協定（全国が参加・自主目標）の根本的な違いを押さえること。

★ ポイント：「なぜ国際的な環境合意は難しいのか」→先進国と途上国の「歴史的排出責任vs現在の経済成長の権利」という対立構造を理解することが核心。`,
