        body: `縮尺は「実際の距離を地図上でどれだけ縮めたか」を表す割合です。計算問題は入試頻出なので確実にマスターしましょう。

■ 縮尺とは
・縮尺2万5千分の1（1/25000）＝実際の25000cmを地図上で1cmに縮めた
・分母が小さいほど「くわしい（大縮尺）」、分母が大きいほど「広い範囲をおおまか（小縮尺）」に表す
・国土地理院の代表的地形図：2万5千分の1、5万分の1

■ 実際の距離の求め方（公式）
実際の距離 ＝ 地図上の長さ × 縮尺の分母

例1）2万5千分の1の地図で4cm
　4cm × 25000 ＝ 100000cm ＝ 1000m ＝ 1km

例2）5万分の1の地図で3cm
　3cm × 50000 ＝ 150000cm ＝ 1500m ＝ 1.5km

■ 単位換算の確認
・100cm ＝ 1m
・1000m ＝ 1km
・つまり 100000cm ＝ 1000m ＝ 1km
→ cmで出た答えを「÷100でm」「÷1000でkm」に直す

■ 逆の計算（地図上の長さを求める）
地図上の長さ ＝ 実際の距離 ÷ 縮尺の分母
例）実際に2km（＝200000cm）を2万5千分の1で表すと
　200000 ÷ 25000 ＝ 8cm

★ ポイント：まず「地図上の長さ×分母」でcmの答えを出し、最後にmやkmに直す。単位換算のミスが最も多い失点原因。

⚠ 注意：「大縮尺」「小縮尺」の言い方に注意。分母が小さい2万5千分の1のほうが「大縮尺（くわしい）」。数字が大きい＝くわしい、ではない。

例）面積を比べる問題：2万5千分の1と5万分の1では、同じ紙の大きさなら5万分の1のほうが2倍広い範囲を表す（縦横それぞれ2倍→面積は4倍広い範囲）。`,
