        heading: '4. 等高線と土地の高低',
        body: `等高線は同じ高さの地点を結んだ線で、土地の起伏（高低）を平面の地図上に表す工夫です。地形図読解の中心テーマです。

■ 等高線の種類（2万5千分の1の場合）
・計曲線（太い線）：50mごと
・主曲線（細い線）：10mごと
→ 5万分の1では、計曲線100mごと・主曲線20mごと

■ 等高線からわかること
①線の間隔がせまい → 傾斜が急（けわしい坂）
②線の間隔が広い → 傾斜がゆるやか（なだらか）
③線が高い方へ食い込む（V字が高い方を向く）→ 谷
④線が低い方へ張り出す → 尾根（山の背）

■ 標高の読み取り
・等高線の数字を読んで高さを判断
・計曲線に書かれた標高（例：100m）を手がかりに、主曲線を数えて求める

■ 地形の見分け方
・扇状地：川が山地から平地に出る所にできる扇形の地形。等高線が同心円状に広がる。水はけがよく果樹園・畑に利用
・三角州（デルタ）：川が海や湖に注ぐ河口にできる。土砂がたまった低く平らな地形。水田・市街地に利用
・台地：周囲より一段高く平らな土地。等高線に囲まれた平坦地

★ ポイント：「間隔せまい＝急」「間隔広い＝ゆるやか」は絶対暗記。等高線を横切る断面図を書かせる問題も、この原則で解ける。

⚠ 注意：扇状地（山ろく・水はけ良・果樹園）と三角州（河口・水はけ悪・水田や市街地）を混同しない。できる場所と土地利用が正反対。

例）等高線の間隔が上流側でせまく、下流側で急に広がっている地形図→山から平地に出た扇状地の可能性が高い。`,
