        body: `お金を融通しあうしくみ（金融）と、その中心にある銀行のはたらきを学びます。

■ 金融とは
・お金が余っている人（貯蓄する人）から、お金を必要とする人（企業・個人）へお金を融通すること
・直接金融：株式・債券で、企業が投資家から直接お金を集める
・間接金融：銀行が預金を集め、それを企業などに貸し出す

■ 銀行のはたらき
・預金の受け入れ：家計や企業から預金を預かる
・貸し出し：集めたお金を企業や個人に貸す
・為替（送金）：離れた相手への支払いを仲立ちする
・利子（利息）：預金者には利子を払い、借り手からは高い利子を取る。その差が銀行の利益

■ 日本銀行（中央銀行）
・日本の中央銀行で、3つの役割をもつ
①発券銀行：紙幣（日本銀行券）を発行できる唯一の銀行
②銀行の銀行：一般の銀行にお金を貸したり預かったりする
③政府の銀行：国のお金（税金など）を管理する
・金融政策：景気を安定させるため、世の中に出回るお金の量を調整する

■ キャッシュレス化
・現金を使わない支払い（クレジットカード・電子マネー・QRコード決済・スマホ決済）が急速に普及
・利点：支払いが速い、記録が残る、防犯になる
・課題：使いすぎ、情報流出、高齢者やお店の対応、災害・停電時に使えないこと

★ ポイント：「銀行は預金者に低い利子を払い、借り手から高い利子を取る。その差が利益」というしくみと、「日本銀行の3つの役割」を確実に。

⚠ 注意：日本銀行は「政府の銀行・銀行の銀行」であって、私たち個人は口座を持てない。個人が使うのは民間の銀行（都市銀行・地方銀行・ゆうちょ銀行など）。

例）会社が工場を建てるお金を銀行から借りる（間接金融）／株式を発行して投資家から集める（直接金融）。どちらもお金を融通する金融のはたらき。`,
