・自動車摩擦：日本車の対米輸出急増でアメリカの雇用が脅かされたとして、日本は「輸出自主規制」を実施し、さらにアメリカ国内に工場を建てる「現地生産」へ転換
・半導体摩擦：日米半導体協定（1986年）で、日本市場での外国製半導体のシェア拡大や、最低価格の維持が取り決められた

