        heading: '2. 内閣と行政のしくみ',
        body: `内閣は法律や予算にもとづいて実際に政治を行う機関です。内閣の構成と、日々の行政を担う省庁の仕組みを見ていきます。

■ 内閣の構成
・内閣総理大臣（首相）と国務大臣（各省庁の大臣など）で構成される合議体
・内閣総理大臣は国会議員の中から国会の議決で指名され、天皇が任命する
・国務大臣の過半数は国会議員でなければならない（憲法第68条）。また国務大臣の任免権は首相が持つ

■ 閣議と行政各部
・閣議：内閣の意思決定を行う会議。原則として全会一致で決定される
・行政各部：財務省・外務省・文部科学省・厚生労働省・経済産業省など、それぞれ専門分野の行政を担当する省庁が置かれる
・庁（例：気象庁・こども家庭庁）は各省に付属する外局として置かれる場合が多い
・行政委員会：政治的な中立性が求められる分野に置かれる合議制の機関（例：公正取引委員会、人事院、国家公安委員会）

■ 行政改革と省庁再編
・2001年の中央省庁再編：それまで1府22省庁だったものを1府12省庁に再編し、行政の効率化・縦割り行政の是正を目指した
・近年の新設庁の例：デジタル庁（2021年・行政のデジタル化推進）、こども家庭庁（2023年・少子化対策や子ども政策の一元化）

■ 議院内閣制のしくみ
・内閣は国会（特に衆議院）の信任にもとづいて成立し、国会に対して連帯して責任を負う
・衆議院で内閣不信任決議が可決された場合、内閣は10日以内に衆議院を解散するか、総辞職しなければならない
・議院内閣制（日本・イギリスなど）は、行政（内閣）と立法（国会）が密接に結びつく制度。対して大統領制（アメリカ）は、行政と立法をより厳格に分離する制度

★ ポイント：「内閣不信任決議→10日以内に解散か総辞職」という手続きは頻出。省庁再編（2001年・1府12省庁）やデジタル庁・こども家庭庁など新設組織も時事として狙われやすい。

⚠ 注意：「議院内閣制」と「大統領制」の違いは記述問題の定番。議院内閣制は内閣が議会の信任に基づく点、大統領制は国民が大統領と議会をそれぞれ別に選ぶ点を対比して説明できるようにする。`,
