        body: `災害が発生した後、地域や生活をどのように立て直していくのか、その仕組みと近年の防災まちづくりの工夫を見ていきます。

■ 災害救助法と被災者支援
・災害救助法：一定規模以上の災害が発生した際に適用され、応急仮設住宅の提供、食品・生活必需品の給与などが行われる
・罹災証明書：住宅などの被害の程度（全壊・大規模半壊・半壊・一部損壊など）を市区町村が証明する書類。被災者生活再建支援金の申請や税の減免、応急仮設住宅の入居などに必要
・被災者生活再建支援法：住宅が全壊するなどの被害を受けた世帯に対し、生活再建のための支援金を支給する制度

■ 復興のプロセス
・応急対応期：人命救助・避難所運営・ライフライン（電気・水道・ガス）の復旧
・復旧期：仮設住宅の建設、道路・鉄道など交通インフラの復旧
・復興期：住宅の再建、産業の再生、まちづくりの見直し（高台移転、防災集団移転促進事業など）

■ 東日本大震災からの復興の教訓
・高台移転：津波被害を教訓に、住宅地を高台に移転する事業が沿岸部で進められた
・「創造的復興」：単に元通りに戻すのではなく、より災害に強い地域づくりを目指す考え方
・原発事故からの復興：避難指示が解除された地域でも、住民の帰還や産業の再生には長い年月がかかっている

■ 減災という考え方
・「防災」（被害を出さないようにする）に対し、「減災」（被害を完全にゼロにはできないという前提で、被害を最小限に抑える）という考え方が近年重視されている
・ハード対策（堤防・防潮堤などの構造物）とソフト対策（避難計画・防災教育・情報伝達）を組み合わせることが減災の基本

■ 防災教育の広がり
・学校での避難訓練、防災の授業（釜石の奇跡：岩手県釜石市の小中学生が日ごろの防災教育の成果で東日本大震災の津波からほぼ全員避難できた事例）
・地域と学校が連携した防災訓練、ハザードマップを使った町歩きなどの実践的な学習が広がっている

★ ポイント：「罹災証明書」「被災者生活再建支援法」「高台移転」「減災」という用語の意味を正確に説明できるようにする。「釜石の奇跡」は防災教育の効果を示す具体例として頻出。

⚠ 注意：「防災」と「減災」は似ているが、「被害をゼロにする」ことを目指すか、「被害を前提にそれを最小化する」ことを目指すかという発想の違いがある点を区別する。`,
