・日本ファクトチェックセンター（JFC）などの専門機関が、SNSで拡散する誤情報・災害時のデマなどを検証し結果を公表している
・災害時には特にデマ（根拠のない噂）が広がりやすく、公式情報（気象庁・自治体・消防など）を確認することが重要

