        body: `高齢化が進む中で、介護を社会全体で支え合うために2000年に創設されたのが介護保険制度です。しくみを具体的に見ていきましょう。

■ 介護保険制度の創設（2000年）
・それまで介護は主に家族が担うものとされてきたが、核家族化・高齢化の進行で家族だけによる介護（介護の社会化以前）が難しくなり、社会全体で支える制度として創設
・「介護の社会化」を実現し、家族の介護負担を軽減することを目的とする

■ 被保険者の区分
・第1号被保険者：65歳以上の人。原因を問わず、要介護・要支援状態と認定されればサービスを利用できる
・第2号被保険者：40歳以上65歳未満の医療保険加入者。特定疾病（加齢に伴う16種類の病気）が原因の場合に限りサービスを利用できる

■ 要介護認定とサービスの利用
・利用を希望する人は市区町村に申請し、訪問調査・主治医の意見書などにもとづいて「要支援1・2」「要介護1〜5」の7段階で認定を受ける
・認定の程度に応じて利用できるサービスの上限額（支給限度額）が決まる
・ケアマネジャー（介護支援専門員）が、利用者に合わせた介護サービス計画（ケアプラン）を作成する

■ 介護サービスの種類
・在宅サービス：訪問介護（ホームヘルプ）、訪問看護、デイサービス（通所介護）など
・施設サービス：特別養護老人ホーム、介護老人保健施設など
・地域密着型サービス：住み慣れた地域で暮らし続けられるよう、小規模な事業所が提供するサービス

■ 介護保険が抱える課題
・介護人材の不足：賃金水準の低さ・仕事のきつさから担い手不足が深刻化し、外国人介護人材（EPA・技能実習・特定技能）の受け入れが拡大
・保険料負担の増加：65歳以上の保険料は制度開始以来上昇を続けており、財政の持続可能性が課題
・2025年問題：団塊の世代（1947〜49年生まれ）が全員75歳以上になる2025年以降、介護・医療の需要がさらに急増すると見込まれる

★ ポイント：「介護保険2000年創設」「第1号被保険者＝65歳以上」「第2号被保険者＝40〜64歳・特定疾病のみ」「要介護認定7段階」という数字と用語を正確に区別する。

⚠ 注意：介護保険は「40歳から保険料を納め始める」が「サービスを実際に使えるのは原則65歳以上（第2号は特定疾病の場合のみ）」という、加入年齢と利用開始年齢のズレがある点に注意。`,
