        body: `少子化に歯止めをかけるため、政府はさまざまな対策を進めてきました。近年の政策の到達点として発足したこども家庭庁の役割を理解しましょう。

■ これまでの少子化対策の経緯
・エンゼルプラン（1994年）：少子化対策として初めて策定された国の総合計画。保育サービスの拡充などを盛り込む
・次世代育成支援対策推進法（2003年）：企業に対しても子育て支援の行動計画策定を求める
・子ども・子育て支援新制度（2015年）：幼稚園・保育所・認定こども園を通じた給付や、地域の子育て支援の充実を図る

■ こども家庭庁の発足（2023年）
・それまで内閣府・厚生労働省・文部科学省などに分かれていた子ども関連の政策を一元化するために新設された行政機関
・「こどもまんなか社会」の実現を掲げ、少子化対策、子どもの貧困対策、児童虐待防止、いじめ対策などを幅広く担当
・こども基本法（2023年施行）とあわせて整備され、子どもの意見を政策に反映させる仕組み（子ども・若者の意見聴取）も重視されている

■ 近年の具体的な少子化対策
・児童手当の拡充：所得制限の撤廃、支給期間の高校生年代までの延長など（近年の制度改正）
・出産育児一時金の増額：出産にかかる経済的負担を軽減するため、支給額が引き上げられてきた
・保育の受け皿拡大：待機児童対策としての保育所整備、幼児教育・保育の無償化（2019年開始、3〜5歳児クラスなど対象）
・育児休業制度の充実：男性の育児休業取得率向上を目指す「産後パパ育休」制度の導入（2022年）

■ 働き方改革と両立支援
・長時間労働の是正、テレワークの普及、企業の子育て支援への取り組み（くるみん認定制度）などにより、仕事と子育ての両立を後押しする政策が進められている
・地方自治体独自の取り組み：住宅支援・保育料無償化など、地域ごとの少子化対策も広がっている

★ ポイント：「こども家庭庁＝2023年発足・少子化対策の一元化」「こども基本法」「幼児教育・保育の無償化2019年」は時事問題として頻出。過去の少子化対策（エンゼルプランなど）とあわせて年表で整理する。

⚠ 注意：少子化対策は「一つの政策で解決する」ものではなく、経済的支援・保育の充実・働き方改革・意識改革など複数の政策を組み合わせる必要がある点を理解する。`,
